#include "dual_sequence_slots.cuh"
#include "dual_state_initialization.hpp"
#include <cstdio>
int main(){try{using namespace tao::dual;Config c;c.layers=1;c.d=4;c.s=2;c.m=3;c.e=8;c.vocab=261;SortedGpuTrainer trainer(initialize(c,713));CpuModel ref(c);for(auto&kv:ref.w)kv.second=trainer.graph.w.at(kv.first)->value.host();auto a=ref.initial(),b=ref.initial();SequenceSlots slots(trainer,2);double worst=0;for(int pass=0;pass<4;++pass){unsigned slot=pass%2;slots.begin(slot,pass<2);for(int i=0;i<3;++i){unsigned tok=17+pass*3+i;auto y=trainer.graph.step(tok);auto gpu=y->value.host(),cpu=ref.step(tok,slot?b:a);for(size_t j=0;j<cpu.size();++j){double e=std::abs(gpu[j]-cpu[j]);worst=std::max(worst,e);if(e>2e-5)throw std::runtime_error("slot isolation");}seed_loss(y,tok+1,i==2);}slots.finish(true);}trainer.update(4);printf("PASS interleaved slots state parity max=%.9g shared_update=%u\n",worst,trainer.steps);return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
